def contact():return f'''<section class="section contact-section" id="contact"><div class="wrap contact-grid"><div class="contact-copy"><p class="eyebrow">LET’S GET IT TAKEN CARE OF</p><h2>A real person.<br>A practical solution.</h2><p>Tell us what’s happening and where you’re located.<br>We’ll help you arrange the next step.</p><span class="mini-label">CALL TO SCHEDULE SERVICE</span>{officephones('contact')}<a class="email" href="mailto:contact@thegreatestplumber.com">contact@thegreatestplumber.com</a><p class="area-note">Emergency? Call Ed directly, 24/7: {emergencyphone()}<br>You can also email <a href="mailto:contact@thegreatestplumber.com">contact@thegreatestplumber.com</a>.</p></div><div class="contact-panel"><h3>Start a service inquiry</h3><p>Prefer email? Fill in your details to prepare a request in your email app.</p><form id="service-request"><div class="field-row"><label>Your name<input name="name" autocomplete="name" maxlength="100" required placeholder="Full name"></label><label>Phone number<input name="phone" type="tel" autocomplete="tel" maxlength="40" required placeholder="Your phone number"></label></div><div class="field-row"><label>Town or city<input name="town" autocomplete="address-level2" maxlength="100" required placeholder="Your service location"></label><label>How can we help?<select name="service" required><option value="">Select a service</option>{''.join(f'<option>{s["name"]}</option>' for s in SERVICES)}<option>Something else</option></select></label></div><label>A few details<textarea name="details" maxlength="2000" required placeholder="Tell us about the issue or the project you have in mind."></textarea></label><button class="btn" type="submit">Prepare email request {icon('arrow')}</button><p class="form-note">Opens your email app; you review and send the request there. An appointment is confirmed only after you speak with our team. For urgent help, please call. <a href="/privacy/">Privacy details</a>.</p><p id="form-status" class="form-status" role="status" hidden></p><noscript><p class="no-js-note">Please call or <a href="mailto:contact@thegreatestplumber.com">email us directly</a> to arrange service.</p></noscript></form></div></div></section>'''
def header():return f'''<a class="skip" href="#main">Skip to content</a><div class="utility"><div class="wrap"><span class="utility-region">YOUR CHICAGOLAND PLUMBER • OVER 40 YEARS OF EXPERIENCE</span><a href="tel:+17734711444"><span class="status-dot"></span>24/7 emergency help: (773) 471-1444 {icon('arrow')}</a></div></div><header class="site-header"><div class="wrap nav"><a class="brand" href="/" aria-label="Ed’s Plumbing and Sewer home"><img src="/assets/logo.webp" alt="Ed’s Plumbing & Sewer Inc." width="720" height="240"></a><button class="menu-toggle" aria-controls="navigation" aria-expanded="false" type="button">Menu <span aria-hidden="true">☰</span></button><nav class="nav-links" id="navigation" aria-label="Main navigation"><a href="/#services">Our services</a><a href="/about/">About Ed’s</a><a href="/#service-area">Service area</a></nav><div class="header-phones">{officephones('header')}</div>{btn('Contact us','/contact-us/')}</div></header>'''
